"""Create public inspection projection and manifest from this dedicated real workflow."""
import hashlib,json
from pathlib import Path
BASE=Path(__file__).resolve().parent
PUB=BASE/'public'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2),encoding='utf-8')
def main():
    snapshot=json.loads((PUB/'snapshot.json').read_text(encoding='utf-8'))
    entries=[
        ('request','準備を依頼','job','模擬データの準備を受け付ける','n8n Webhook','専用の認証付きローカル経路。公開ページからは実行できません。','n8n','n0'),
        ('dify','架空データを組み立てる','program','AI組織と案件のサンプルを作る','Dify Code / Python','実Difyで固定データを組み立てます。LLM推論は行いません。','dify','n1'),
        ('validate','結果を確かめる','program','Difyの成功と出力を検査','n8n Code','成功状態と出力契約を確認してからjobへ渡します。','n8n','n2'),
        ('job','模擬jobを保存','job','重複しない模擬実行を作る','PoC adapter / SQLite','同じ冪等キーの依頼は同じjob IDを返します。','n8n','n3'),
        ('observe','状態を観測','program','jobの完了と結果を取得','n8n HTTP Request','短い模擬jobを待って取得。長時間実AI運用の証明ではありません。','n8n','n5'),
        ('result','操作モックへ渡す','job','検証済みの架空データを表示','seed.json / Browser','実出力をseed.jsonへ保存。公開画面の操作はブラウザ内だけで完結します。','n8n','n6')]
    nodes=[dict(zip(['id','label','kind','job','implementation','explanation'],r[:6]),source={'engine':r[6],'node_id':r[7]}) for r in entries]
    graph={'schema_version':1,'style':'job-agent-directed-graph','title':'モックの準備工程','source_snapshot_sha256':sha(PUB/'snapshot.json'),'nodes':nodes,'edges':[{'source':a['id'],'target':b['id'],'label':'結果を渡す'} for a,b in zip(nodes,nodes[1:])]}
    write(PUB/'inspection.json',graph)
    url='https://viewer.example.com/viewer/agent-workspace-pipeline/'  # example URL; set your own published viewer URL
    manifest={'project':'project-a','scope':'new-application','frameworks':['n8n','dify','openspec','langgraph'],'n8n_export':'evidence/n8n.json','dify_export':'evidence/dify.json','job_contract':'Existing authenticated PoC adapter: job_id/status/progress/result/error; Idempotency-Key; completed zlib64 mock result decoded and verified against fixture, then copied to public/seed.json','verification':'tests/*.test.mjs (node --test); evidence/ is regenerated by prepare.py and verify_public.py and is not included','migrate_legacy':False,'coding_delegation':{'default_model':'example-coding-model','reasoning_effort':'medium','unavailable':'stop-and-report'},'public_view':{'url':url,'snapshot':'public/snapshot.json','verification':'evidence/public-view.json','read_only':True,'authentication':'none'},'inspection_view':{'style':'job-agent-directed-graph','default':True,'url':url,'graph':'public/inspection.json','verification':'evidence/inspection-view.json','read_only':True,'authentication':'none'}}
    write(BASE/'manifest.json',manifest)
    (BASE/'evidence').mkdir(exist_ok=True)
    for name in ['public-view.json','inspection-view.json','browser.json']:
        path=BASE/'evidence'/name
        if not path.exists():write(path,{'status':'pending'})
    print(json.dumps({'status':'built','nodes':len(nodes),'edges':len(graph['edges'])}))
if __name__=='__main__':main()
